/**
 * The shape of the glossary: shorthands, name parts, compounds, the pKa
 * ladder and the reactions, filed by functional group.
 *
 * Two kinds of source, kept apart on purpose:
 *   - GlossaryData is GENERATED by scripts/glossary.py with RDKit, so every
 *     structure here was drawn by RDKit and every name part was checked
 *     against its structure (glossary.generated.ts);
 *   - the curriculum's reaction table and the pKa numbers are read at run time
 *     from where they already live (glossaryModel.ts), never copied.
 *
 * Pure data, no React, so the node test suite can walk all of it.
 */
import type { GuideFigure } from "../guide/types";

/** The ten functional group families the owner listed, in his order. */
export type FamilyId =
  | "alkanes"
  | "alkenes"
  | "alkynes"
  | "aromatics"
  | "haloalkanes"
  | "alcohols"
  | "amines"
  | "carbonyls"
  | "acids"
  | "esters";

export type ShorthandKind = "solvent" | "group" | "reagent";

export interface GlossaryShorthand {
  /** As a student sees it written: "DMSO", "tBu", "Jones". */
  readonly short: string;
  /** Other ways it is written, searched like the short form. */
  readonly aliases: readonly string[];
  readonly full: string;
  readonly kind: ShorthandKind;
  /** One line: what it is for. */
  readonly use: string;
  readonly smiles: string;
  readonly figure: GuideFigure;
}

/** One part of a name ("-one", "phen-") and what it says about the structure. */
export interface GlossaryPart {
  readonly text: string;
  readonly means: string;
}

export interface GlossaryCompound {
  readonly name: string;
  readonly smiles: string;
  readonly family: FamilyId;
  /** Keys into GlossaryData.parts, in the order they explain the name. */
  readonly parts: readonly string[];
  readonly figure: GuideFigure;
  /**
   * The owner's EWG / EDG lecture point for this compound, set only when it
   * has one benzene ring carrying one group (found by RDKit, RING_RULES in
   * scripts/glossary.py). `effect` uses the Unit 3 pools' words.
   */
  readonly ring?: GlossaryRingNote;
}

/** "the C=O" and "meta director, deactivating". */
export interface GlossaryRingNote {
  readonly group: string;
  readonly effect: string;
}

export interface GlossaryPkaExample {
  readonly smiles: string;
  readonly figure: GuideFigure;
}

export interface GlossarySubstituent {
  readonly name: string;
  readonly smiles: string;
  /** edg: donates, activates, o/p. ewg: withdraws, deactivates, meta. halogen: deactivates but o/p. */
  readonly effect: "edg" | "ewg" | "halogen";
  readonly figure: GuideFigure;
}

/** One reaction line of documentation/ORGO2-REAGENT-REFERENCE.md, word for word. */
export interface GlossaryReferenceLine {
  readonly section: number;
  readonly topic: string;
  /** The words before the first colon: the transformation's name. */
  readonly title: string;
  /** The words after it: reagents and conditions. Empty when the line had no colon. */
  readonly detail: string;
  /** Families it starts from. Empty for an analytical line with nothing to file. */
  readonly families: readonly FamilyId[];
}

export interface GlossaryData {
  readonly families: readonly FamilyId[];
  readonly shorthands: readonly GlossaryShorthand[];
  readonly parts: Readonly<Record<string, GlossaryPart>>;
  readonly compounds: readonly GlossaryCompound[];
  /** Keyed by the curriculum's PkaSiteId. */
  readonly pka: Readonly<Record<string, GlossaryPkaExample>>;
  readonly substituents: readonly GlossarySubstituent[];
  readonly reference: readonly GlossaryReferenceLine[];
}

/* ------------------------------------------------------------------ */
/* Personal definitions: the typed hook, NOT built yet                  */
/* ------------------------------------------------------------------ */

/**
 * Who wrote an entry. Every entry today is Blueberry's. A student's own saved
 * definition (owner, item 27) will carry `student` and the page draws an
 * award badge on it, so it reads as theirs.
 */
export type GlossaryOrigin = "blueberry" | "student";

/** A definition a student saved. Not stored anywhere yet. */
export interface PersonalDefinition {
  readonly id: string;
  readonly term: string;
  readonly definition: string;
  /** ISO time it was saved. */
  readonly savedAt: string;
  /** The glossary entry it hangs off, if it was saved from one. */
  readonly entryId?: string;
}

/**
 * The seam a future store plugs into, the same external store shape as
 * settings/pka.ts (subscribe plus getSnapshot, read with useSyncExternalStore).
 * Nothing implements it yet; glossaryModel.ts accepts a snapshot so the page
 * and the tests already merge personal entries with the built ones.
 */
export interface PersonalDefinitionSource {
  getSnapshot(): readonly PersonalDefinition[];
  subscribe(listener: () => void): () => void;
  save(definition: PersonalDefinition): void;
  remove(id: string): void;
}
